def compute(vars):
    purchase_price = vars["Purchase Price"]
    fair_value_identifiable_net_assets = vars["Fair Value of Identifiable Net Assets"]
    goodwill = purchase_price - fair_value_identifiable_net_assets
    return {
        "value": goodwill,
        "trace": {
            "Purchase Price": purchase_price,
            "Fair Value of Identifiable Net Assets": fair_value_identifiable_net_assets,
            "output_meta": {
                "currency": "$",
                "scale": "millions",
                "unit": None
            }
        }
    }
